def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string into characters (ignoring spaces)
    chars = test.split()

    if not chars:
        return {}

    # Count occurrences of each character
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Find the maximum count
    max_count = max(counts.values())

    # Return a dictionary containing only the characters with the maximum count
    return {char: count for char, count in counts.items() if count == max_count}

def check_dict_case(dict):
    if not dict:
        return False

    keys = list(dict.keys())
    # Check if all keys are strings
    if not all(isinstance(k, str) for k in keys):
        return False

    all_lower = all(k.islower() for k in keys)
    all_upper = all(k.isupper() for k in keys)

    return all_lower or all_upper

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
